pub fn mnemonic_doc(m: &str) -> Option<&'static str> { MNEMONICS.iter().find(|(n, _)| *n == m).map(|(_, d)| *d) }
pub fn directive_doc(d: &str) -> Option<&'static str> { DIRECTIVES.iter().find(|(n, _)| *n == d).map(|(_, d)| *d) }
